/* 拾音 · 单文件 Cloudflare Worker（后台在线编辑器粘贴部署）
   部署：Workers 创建 → 粘贴本文件 → Settings 绑定 Durable Object：
       变量名 SIGNALING / 类名 SignalingRoom（选 new class，带 SQLite）。
   前端页面已 base64 内联，无需静态资源绑定。 */
const PAGE_B64 = "";
function decodePage(){var b=atob(PAGE_B64);var a=Uint8Array.from(b,function(c){return c.charCodeAt(0)});return new TextDecoder().decode(a)}
var PAGE=decodePage();

/* =========================================================
   拾音 · 信令房间核心（room-core.js）
   与运行环境无关：Node 本地测试与 Cloudflare Durable Object 共用同一份逻辑，
   保证「本地跑通的语义 = 线上语义」。

   职责：
   - 房间成员管理（一对一上限 2，群聊上限 4）
   - 成员加入 / 离开的广播
   - ICE 信令的点对点转发（不做解析，只透传 SDP / candidate）
   - 「挂断即消」：房主离开则整间关闭；房间清空则回收

   协议（JSON 文本帧，字段 t = type）：
   客户端 -> 服务端：
     { t:"sig", to:<peerId>, data:{...} }   转发给指定成员
   服务端 -> 客户端：
     { t:"joined",     id:<selfId>, host:<bool>, peers:[<id>...] }
     { t:"peer-joined",id:<peerId> }
     { t:"peer-left",  id:<peerId> }
     { t:"sig",        from:<peerId>, data:{...} }
     { t:"full" }                              房间已满
     { t:"closed" }                            房间已关闭（房主挂断 / 已失效）
   ========================================================= */

const MAX_SOLO = 2;
const MAX_GROUP = 4;

/**
 * 创建一个房间实例。
 * @param {object} opts
 * @param {number} opts.max      房间人数上限
 * @param {function} opts.send    (connId, obj) => void   向某条连接发送消息
 * @param {function} [opts.onEmpty]  房间清空时回调（用于回收 DO 状态）
 */
function createRoom(opts) {
  const max = opts.max || MAX_SOLO;
  const send = opts.send;
  const onEmpty = opts.onEmpty || function () {};

  const peers = new Map(); // connId -> { id, joinedAt }
  let hostId = null;       // 第一个加入者即房主
  let closed = false;
  let seq = 0;

  function newId() {
    // 用于确定性协商：id 可比较（字符串字典序），小的一方发起 offer
    seq += 1;
    const s = String(seq).padStart(3, '0');
    const r = Math.random().toString(36).slice(2, 6);
    return 'p' + s + r;
  }

  function roster() {
    return [...peers.values()].map(function (p) { return p.id; });
  }

  return {
    get size() { return peers.size; },
    get hostId() { return hostId; },
    isClosed() { return closed; },

    /** 成员加入，返回分配到的 peerId（失败返回 null） */
    join(connId) {
      if (closed) { send(connId, { t: 'closed' }); return null; }
      if (peers.size >= max) { send(connId, { t: 'full' }); return null; }

      const id = newId();
      peers.set(connId, { id: id, joinedAt: Date.now() });
      if (!hostId) hostId = id;

      // 先告知加入者自己的身份与现有名单（不含自己）
      const others = roster().filter(function (x) { return x !== id; });
      send(connId, { t: 'joined', id: id, host: id === hostId, peers: others });

      // 再广播给房间其他成员
      for (const [c, p] of peers) {
        if (c !== connId) send(c, { t: 'peer-joined', id: id });
      }
      return id;
    },

    /** ICE 信令转发 */
    signal(fromConnId, msg) {
      if (closed) return;
      const from = peers.get(fromConnId);
      if (!from || !msg || !msg.to) return;
      for (const [c, p] of peers) {
        if (p.id === msg.to && c !== fromConnId) {
          send(c, { t: 'sig', from: from.id, data: msg.data });
        }
      }
    },

    /** 成员离开；房主离开 => 关闭整间 */
    leave(connId) {
      const p = peers.get(connId);
      if (!p) return;
      peers.delete(connId);

      if (p.id === hostId) {
        // 挂断即消：房主离开，通知所有剩余成员并关闭
        closed = true;
        for (const [c] of peers) send(c, { t: 'closed' });
        peers.clear();
        onEmpty();
        return;
      }

      for (const [c] of peers) send(c, { t: 'peer-left', id: p.id });
      if (peers.size === 0) { closed = true; onEmpty(); }
    }
  };
}


/* =========================================================
   拾音 · ICE 服务器下发（turn.js）
   返回给前端的 STUN / TURN 列表。

   支持三种来源：
   1. STUN_URLS          ：逗号分隔的 STUN 列表（默认用 Cloudflare STUN）
   2. TURN_URL/USERNAME/CREDENTIAL ：静态自建 TURN（如 coturn）
   3. CF_TURN_KEY_ID + CF_TURN_API_TOKEN ：Cloudflare Calls 托管 TURN，
      服务端用 API Token 换取短期凭证，前端不接触长期密钥（推荐）。
   ========================================================= */

function splitList(v) {
  return String(v || '').split(',').map(function (s) { return s.trim(); }).filter(Boolean);
}

async function cloudflareTurn(env) {
  const keyId = env.CF_TURN_KEY_ID;
  const token = env.CF_TURN_API_TOKEN;
  if (!keyId || !token) return null;
  try {
    const ttl = parseInt(env.TURN_TTL || '86400', 10);
    const resp = await fetch(
      'https://rtc.live.cloudflare.com/v1/turn/keys/' + keyId + '/credentials/generate-ice-servers',
      {
        method: 'POST',
        headers: {
          'Authorization': 'Bearer ' + token,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ ttl: ttl })
      }
    );
    if (!resp.ok) return null;
    const data = await resp.json();
    // Cloudflare 返回 { iceServers: { urls:[...], username, credential } }
    if (data && data.iceServers) return Array.isArray(data.iceServers) ? data.iceServers : [data.iceServers];
    return null;
  } catch (e) {
    return null;
  }
}

async function buildIceServers(env) {
  const ice = [];

  // 1) STUN
  const stuns = splitList(env.STUN_URLS);
  const stunList = stuns.length ? stuns : ['stun:stun.cloudflare.com:3478'];
  for (const u of stunList) ice.push({ urls: u });

  // 2) Cloudflare 托管 TURN（优先）
  const cf = await cloudflareTurn(env);
  if (cf) { for (const s of cf) ice.push(s); }

  // 3) 静态自建 TURN（兜底 / 叠加）
  if (env.TURN_URL && env.TURN_USERNAME && env.TURN_CREDENTIAL) {
    ice.push({
      urls: splitList(env.TURN_URL),
      username: env.TURN_USERNAME,
      credential: env.TURN_CREDENTIAL
    });
  }

  return ice;
}

async function handleTurn(env) {
  const iceServers = await buildIceServers(env);
  return new Response(JSON.stringify({ iceServers: iceServers }), {
    headers: {
      'content-type': 'application/json; charset=utf-8',
      'cache-control': 'no-store',
      'access-control-allow-origin': '*'
    }
  });
}


/* =========================================================
   拾音 · Durable Object 信令房间（signaling.js）
   每个房间码对应一个 DO 实例，天然做到房间隔离与状态一致。
   复用 room-core.js，保证与本地测试同源。
   ========================================================= */


class SignalingRoom {
  constructor(state, env) {
    this.state = state;
    this.env = env;
    this.conns = new Map(); // connId -> WebSocket
    this.room = null;
  }

  async fetch(request) {
    const url = new URL(request.url);
    const mode = url.searchParams.get('mode') === 'group' ? 'group' : 'solo';

    const pair = new WebSocketPair();
    const client = pair[0];
    const server = pair[1];

    // 使用 hibernation 友好的可接受 WebSocket
    server.accept();

    if (!this.room || this.room.isClosed()) {
      const max = mode === 'group' ? MAX_GROUP : MAX_SOLO;
      const self = this;
      this.room = createRoom({
        max: max,
        send: function (connId, obj) {
          const ws = self.conns.get(connId);
          if (ws) { try { ws.send(JSON.stringify(obj)); } catch (e) {} }
        },
        onEmpty: function () { self.room = null; }
      });
    }

    const connId = 'c' + Math.random().toString(36).slice(2) + Date.now().toString(36);
    this.conns.set(connId, server);

    // 尝试加入（可能因满员被拒）
    this.room.join(connId);

    server.addEventListener('message', (ev) => {
      let m;
      try { m = JSON.parse(ev.data); } catch (e) { return; }
      if (m && m.t === 'sig' && this.room) this.room.signal(connId, m);
    });

    const cleanup = () => {
      this.conns.delete(connId);
      if (this.room) this.room.leave(connId);
    };
    server.addEventListener('close', cleanup);
    server.addEventListener('error', cleanup);

    return new Response(null, { status: 101, webSocket: client });
  }
}


export { SignalingRoom };
export default {
  async fetch(request, env) {
    const url = new URL(request.url); const path = url.pathname;
    if (path === '/ws') {
      if ((request.headers.get('Upgrade')||'').toLowerCase() !== 'websocket') return new Response('Expected WebSocket upgrade',{status:426});
      const room=(url.searchParams.get('room')||'').toUpperCase();
      const mode=url.searchParams.get('mode')==='group'?'group':'solo';
      if(!room||room.length<4) return new Response('Invalid room',{status:400});
      return env.SIGNALING.get(env.SIGNALING.idFromName(mode+':'+room)).fetch(request);
    }
    if (path === '/api/turn') {
      if (request.method==='OPTIONS') return new Response(null,{status:204,headers:{'access-control-allow-origin':'*'}});
      return handleTurn(env);
    }
    if (path === '/api/config') {
      return new Response(JSON.stringify({maxGroup:parseInt(env.MAX_GROUP||'4',10),prefix:env.PREFIX||'shiyin',reconnectSeconds:parseInt(env.RECONNECT_SECONDS||'60',10)}),{headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});
    }
    if (path === '/' || path === '/index.html') return new Response(PAGE,{headers:{'content-type':'text/html; charset=utf-8'}});
    return new Response('Not Found',{status:404});
  }
};
